const canvas=document.querySelector('#scene'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s),hud=$('#hud'),overlay=$('#overlay');let W=0,H=0,dpr=1,playing=false,paused=false,playerX=0,aim={x:0,y:0},score=0,hp=100,mag=12,lastShot=0,reloadUntil=0,spawnTimer=0,elapsed=0,wave=1,shake=0,flash=0,best=+(localStorage.redlineBest||0),enemies=[],particles=[],splats=[],keys={},mobile=matchMedia('(pointer:coarse)').matches,joy={x:0,y:0},firing=false,last=performance.now(),shotId=0;
if(mobile)document.body.classList.add('mobile');$('#best').textContent=String(best).padStart(3,'0');
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);if(!aim.x){aim.x=W/2;aim.y=H*.51}}
addEventListener('resize',resize);resize();
const rnd=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function project(x,y,z){let f=H*.91/(z+1.6);return{x:W/2+(x-playerX)*f,y:H*.39+(1.65-y)*f,s:f}}
function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function line(a,b,color,width=1){ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}
function drawWorld(t){let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#101416');sky.addColorStop(.4,'#252526');sky.addColorStop(.405,'#16191a');sky.addColorStop(1,'#080a0b');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
// distant sealed bulkhead
let farL=project(-6,0,34),farR=project(6,0,34),farTop=project(0,5.5,34);poly([{x:farL.x,y:farTop.y},{x:farR.x,y:farTop.y},{x:farR.x,y:H},{x:farL.x,y:H}],'#171a1b');
// corridor side walls
for(let side of [-1,1]){let n=project(side*6,0,34),top=project(side*6,5.5,34),near=project(side*6,0,.2),nt=project(side*6,5.5,.2);poly([top,n,near,nt],side<0?'#202324':'#191c1d');let edge=project(side*6,0,1.2);line(edge,near,'#464442',2);for(let z=4;z<33;z+=4){let a=project(side*6,5.2,z),b=project(side*6,0,z);line(a,b,'#ffffff0d');let seam=project(side*6,0,z);line(project(-6,0,z),project(6,0,z),'#ffffff0c')}}
// floor plane
let fl=project(-6,0,34),fr=project(6,0,34),nl=project(-6,0,.2),nr=project(6,0,.2);poly([fl,fr,nr,nl],ctx.createLinearGradient(0,H*.4,0,H).addColorStop(0,'#252727'),ctx.createLinearGradient(0,H*.4,0,H).addColorStop(1,'#121415'));
// floor seams & perspective rails
for(let z=2;z<36;z+=2.5){let y=project(0,0,z).y;line(project(-6,0,z),project(6,0,z),`rgba(182,174,157,${.025+1/(z*z)*.6})`)}for(let x of [-4.7,4.7])line(project(x,0,34),project(x,0,.3),'#716a5c18',2);
// ceiling braces and cold lamps
for(let z=4;z<34;z+=6){let a=project(-6,5.35,z),b=project(6,5.35,z);line(a,b,'#aaa49516',2);for(let x of [-3.6,3.6]){let p=project(x,5.38,z);ctx.fillStyle='#b6c4bd';ctx.globalAlpha=.5/(1+z*.035);ctx.fillRect(p.x-p.s*.52,p.y,p.s*1.04,Math.max(1,p.s*.1));ctx.globalAlpha=1}}
// distant warning light
let lamp=project(0,4.5,34);let pulse=.6+Math.sin(t*.004)*.3;ctx.fillStyle=`rgba(227,58,43,${pulse})`;ctx.fillRect(lamp.x-2,lamp.y,4,2);
// warning marks
for(let side of [-1,1])for(let z=8;z<28;z+=12){let p=project(side*5.94,1.2,z);ctx.fillStyle='#9b372d';ctx.globalAlpha=.45;ctx.fillRect(p.x-p.s*.17,p.y,p.s*.34,p.s*.13);ctx.globalAlpha=1}
}
function drawEnemy(e,t){let p=project(e.x,0,e.z),s=p.s*(e.scale||1);if(s<1)return;let hit=e.hitUntil>t,phase=e.phase;ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);let sway=Math.sin(t*.004+phase)*.07;ctx.translate(sway,0);
// shadow
ctx.fillStyle='#0009';ctx.beginPath();ctx.ellipse(0,0,.69,.14,0,0,Math.PI*2);ctx.fill();
// limbs, angular biohazard creature
let skin=hit?'#b8aaa0':'#484341',dark=hit?'#69514d':'#292829',blood='#8f201e';ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle=dark;ctx.lineWidth=.25;ctx.beginPath();ctx.moveTo(-.25,-.1);ctx.lineTo(-.34,.65);ctx.lineTo(-.29,1.08);ctx.moveTo(.23,-.1);ctx.lineTo(.35,.55);ctx.lineTo(.31,1.04);ctx.stroke();
// torso silhouette
poly([{x:-.39,y:1.04},{x:-.46,y:1.44},{x:-.31,y:1.88},{x:-.2,y:2.06},{x:.21,y:2.04},{x:.37,y:1.68},{x:.42,y:1.2},{x:.25,y:.92},{x:-.25,y:.91}],skin);
// shoulders + arms
ctx.strokeStyle=skin;ctx.lineWidth=.22;ctx.beginPath();ctx.moveTo(-.34,1.78);ctx.lineTo(-.59,1.43);ctx.lineTo(-.54,.97);ctx.moveTo(.33,1.76);ctx.lineTo(.57,1.38);ctx.lineTo(.48,.91);ctx.stroke();
// neck/head
ctx.fillStyle=dark;ctx.fillRect(-.12,1.97,.24,.22);ctx.fillStyle=skin;ctx.beginPath();ctx.ellipse(0,2.25,.25,.3,.04,0,Math.PI*2);ctx.fill();
// glowing core
let glow=ctx.createRadialGradient(0,1.52,.02,0,1.52,.4);glow.addColorStop(0,hit?'#fff':'#ffb3a0');glow.addColorStop(.2,hit?'#ffc2ad':'#e65a43');glow.addColorStop(1,'#8e211d00');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(0,1.52,.4,0,Math.PI*2);ctx.fill();ctx.fillStyle=hit?'#ffe9d9':'#f27759';ctx.beginPath();ctx.moveTo(-.13,1.69);ctx.lineTo(-.08,1.42);ctx.lineTo(.08,1.37);ctx.lineTo(.17,1.58);ctx.lineTo(.02,1.72);ctx.fill();
// eye slits
ctx.fillStyle='#ff5945';ctx.fillRect(-.15,2.27,.09,.035);ctx.fillRect(.07,2.27,.09,.035);
// torn red patches
ctx.fillStyle=blood;for(let i=0;i<4;i++){let x=Math.sin(phase*9+i*7)*.29,y=1.05+((i*37)%85)/100;ctx.beginPath();ctx.ellipse(x,y,.035,.075,.3,0,Math.PI*2);ctx.fill()}
// blood strands hanging from silhouette
if(e.wounds>0){ctx.strokeStyle='#94221e';ctx.lineWidth=.035;for(let i=0;i<Math.min(e.wounds,4);i++){let x=-.22+i*.13;let len=.1+Math.sin(t*.005+i)*.04;ctx.beginPath();ctx.moveTo(x,1.1);ctx.lineTo(x+.015,1.1-len);ctx.stroke();ctx.fillStyle='#a92a22';ctx.beginPath();ctx.arc(x+.015,1.1-len,.043,0,7);ctx.fill()}}
ctx.restore();e.screen={x:p.x,y:p.y-1.3*s,w:.75*s,h:1.95*s,coreY:p.y-.96*s};}
function drawSplats(){for(let s of splats){let p=project(s.x,.015,s.z),r=s.r*p.s*.35;ctx.globalAlpha=s.a;ctx.fillStyle=s.color;ctx.beginPath();ctx.ellipse(p.x,p.y,r,r*.18,s.rot,0,Math.PI*2);ctx.fill();for(let j=0;j<3;j++){ctx.beginPath();ctx.ellipse(p.x+r*rnd(-.8,.8),p.y+rnd(-2,2),r*.1,r*.14,0,0,7);ctx.fill()}}ctx.globalAlpha=1}
function render(t){let dt=Math.min(.04,(t-last)/1000);last=t;if(playing&&!paused)update(dt,t);ctx.save();if(shake>0){ctx.translate(rnd(-shake,shake),rnd(-shake,shake));shake*=.88}drawWorld(t);drawSplats();enemies.sort((a,b)=>b.z-a.z);for(let e of enemies)drawEnemy(e,t);drawParticles(dt);drawGun(t);if(flash>0){ctx.fillStyle=`rgba(255,221,180,${flash})`;ctx.fillRect(0,0,W,H);flash*=.64}ctx.restore();requestAnimationFrame(render)}
function drawGun(t){if(!playing)return;let recoil=Math.max(0,1-(t-lastShot)/190);let s=Math.min(W,H)/650;ctx.save();ctx.translate(W/2+W*.19,H+20+recoil*22);ctx.scale(s,s);let g=ctx.createLinearGradient(-30,-30,40,130);g.addColorStop(0,'#545553');g.addColorStop(.45,'#252829');g.addColorStop(1,'#111414');poly([{x:-36,y:100},{x:-30,y:0},{x:-21,y:-40},{x:17,y:-43},{x:27,y:4},{x:37,y:35},{x:32,y:105}],g,'#79766d');poly([{x:-21,y:-38},{x:15,y:-40},{x:11,y:-55},{x:-14,y:-55}],'#8b8b83');ctx.fillStyle='#cf4937';ctx.fillRect(-2,-51,9,3);poly([{x:-33,y:88},{x:-20,y:80},{x:-14,y:125},{x:-32,y:140}],'#272421');ctx.restore()}
function drawParticles(dt){for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=p.g*dt;if(p.life<=0){particles.splice(i,1);continue}ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.fill()}ctx.globalAlpha=1}
function burst(x,y,n=15){for(let i=0;i<n;i++){let a=rnd(0,Math.PI*2),v=rnd(25,210);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v-rnd(10,65),g:rnd(120,290),r:rnd(1.2,4.6),life:rnd(.28,1.05),max:1.05,color:['#e94d39','#ad1d1b','#751615','#df8063','#f4e3d1'][Math.floor(Math.random()*5)]})}}
function update(dt,t){elapsed+=dt;playerX=clamp(playerX+((keys.a||keys.arrowleft)?-1:0)+((keys.d||keys.arrowright)?1:0)+joy.x,-4.15,4.15);if(keys.w||keys.arrowup||joy.y<-.3)elapsed+=dt*.4;wave=1+Math.floor(score/10);$('#wave').textContent=String(wave).padStart(2,'0');spawnTimer-=dt;if(spawnTimer<=0){enemies.push({x:rnd(-4.2,4.2),z:rnd(21,29),speed:rnd(.48,.76)+wave*.04,hp:2+(wave>2?1:0),phase:rnd(0,6),scale:rnd(.88,1.13),wounds:0});spawnTimer=Math.max(.48,1.65-wave*.055)*rnd(.65,1.2)}for(let i=enemies.length-1;i>=0;i--){let e=enemies[i];e.z-=e.speed*dt;if(e.hitUntil<t)e.hitUntil=0;if(e.z<1.8){enemies.splice(i,1);damage(16);continue}}if(reloadUntil&&t>reloadUntil){reloadUntil=0;mag=12;$('#mag').textContent=mag;$('#toast').style.opacity=0}if(firing&&mobile)shoot(t);if(keys.r)reload(t);if(hp<=0)endGame()}
function damage(n){hp=Math.max(0,hp-n);$('#hptext').textContent=hp;$('#hpbar').style.width=hp+'%';$('#damage').style.opacity='.8';setTimeout(()=>$('#damage').style.opacity='0',190);shake=8;flash=.08}
function shoot(t){if(!playing||paused||t-lastShot<195||reloadUntil)return;if(mag<=0){reload(t);return}lastShot=t;mag--;$('#mag').textContent=mag;flash=.34;shake=3;let hit=null;for(let e of enemies){if(!e.screen)continue;let r=e.screen,dx=(aim.x-r.x)/(r.w*.66),dy=(aim.y-r.coreY)/(r.h*.72);if(dx*dx+dy*dy<1.2&&(!hit||e.z<hit.z))hit=e}if(hit){hit.hp--;hit.hitUntil=t+110;hit.wounds++;let x=hit.screen.x,y=hit.screen.coreY;burst(x,y,hit.hp<=0?27:12);if(hit.hp<=0){score++;$('#score').textContent=String(score).padStart(3,'0');if(score>best){best=score;localStorage.redlineBest=best;$('#best').textContent=String(best).padStart(3,'0')}splats.push({x:hit.x,z:Math.max(1,hit.z-1),r:rnd(.55,1.1),a:.85,color:'#661918',rot:rnd(-.3,.3)});if(splats.length>24)splats.shift();enemies.splice(enemies.indexOf(hit),1);if(navigator.vibrate)navigator.vibrate(24)}$('#cross').classList.add('hit');setTimeout(()=>$('#cross').classList.remove('hit'),90)}else{burst(aim.x,aim.y,4)}}
function reload(t){if(!playing||paused||mag===12||reloadUntil)return;reloadUntil=t+1050;$('#toast').textContent='RELOADING';$('#toast').style.opacity=1}
function start(){score=0;hp=100;mag=12;wave=1;elapsed=0;playerX=0;spawnTimer=.4;enemies=[];particles=[];splats=[];playing=true;paused=false;hud.style.display='block';overlay.style.display='none';$('#pause').style.display='block';$('#score').textContent='000';$('#hptext').textContent='100';$('#hpbar').style.width='100%';$('#mag').textContent=mag;$('#description').textContent='Something got out. The corridor is yours to keep. Make every round count.';$('#pause').textContent='Ⅱ  PAUSE'}
function endGame(){playing=false;hud.style.display='none';overlay.style.display='grid';$('#pause').style.display='none';$('#description').textContent=`You held the line for ${Math.floor(elapsed)} seconds and cleared ${score} ${score===1?'threat':'threats'}. The sector is still hot.`;$('#start').textContent='RUN IT BACK  ↗';$('#damage').style.opacity='0'}
$('#start').onclick=start;$('#pause').onclick=()=>{if(!playing)return;paused=!paused;$('#pause').textContent=paused?'▶  RESUME':'Ⅱ  PAUSE';if(paused){overlay.style.display='grid';$('.eyebrow').textContent='SECTOR 07  ·  PAUSED';$('h1').innerHTML='CATCH YOUR<span>BREATH.</span>';$('#description').textContent='The corridor can wait. Tap resume when you are ready.';$('#start').textContent='RESUME  ↗'}else{overlay.style.display='none';$('.eyebrow').textContent='SECTOR 07  ·  CONTAINMENT FAILED'}};
addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))e.preventDefault();if(e.key.toLowerCase()==='r')reload(performance.now())});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
canvas.addEventListener('pointermove',e=>{if(!mobile){aim.x=e.clientX;aim.y=e.clientY}});canvas.addEventListener('pointerdown',e=>{if(playing&&!mobile){aim.x=e.clientX;aim.y=e.clientY;shoot(performance.now())}});$('#fire').addEventListener('pointerdown',e=>{e.preventDefault();firing=true;shoot(performance.now())});addEventListener('pointerup',()=>firing=false);$('#reload').onclick=()=>reload(performance.now());
const stick=$('#stick');stick.addEventListener('pointerdown',e=>{stick.setPointerCapture(e.pointerId);moveJoy(e)});stick.addEventListener('pointermove',e=>{if(e.buttons)moveJoy(e)});stick.addEventListener('pointerup',()=>joy={x:0,y:0});function moveJoy(e){let r=stick.getBoundingClientRect(),x=(e.clientX-r.left-r.width/2)/(r.width/2),y=(e.clientY-r.top-r.height/2)/(r.height/2),d=Math.hypot(x,y);joy={x:clamp(x,-1,1),y:clamp(y,-1,1)};stick.style.setProperty('--x',`${clamp(x,-1,1)*24}px`)}
requestAnimationFrame(render);

